:root {
  --strip-bg: #ffffff;
  --strip-border: #e0d6c8;
  --header-bg: #1a1a2e;
  --header-text: #ffffff;
  --badge-bg: #f5c518;
  --badge-text: #1a1a2e;
  --date-text: #a0a8c0;
  --frame-bg: #fdf8f0;
  --frame-border: #d4c9b8;
  --frame-1-accent: #ff6b9d;
  --frame-2-accent: #6bceff;
  --frame-3-accent: #6bffb8;
  --frame-4-accent: #ffb86b;
  --caption-text: #666666;
  --footer-bg: #faf6f0;
  --footer-text: #888888;
  --btn-bg: #1a1a2e;
  --btn-text: #ffffff;
}

article.booth-strip {
  background: var(--strip-bg);
  border: 2px solid var(--strip-border);
  border-radius: 12px;
  width: 460px;
  overflow: hidden;
}

.strip-header {
  background: var(--header-bg);
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 16px;
}

.booth-icon {
  font-size: 22px;
}

.header-text {
  flex: 1;
}

.strip-title {
  font-size: 16px;
  font-weight: 700;
  color: var(--header-text);
  margin: 0;
  line-height: 1.2;
}

.strip-date {
  font-size: 11px;
  color: var(--date-text);
  margin: 0;
  line-height: 1.4;
}

.strip-badge {
  background: var(--badge-bg);
  color: var(--badge-text);
  font-size: 11px;
  font-weight: 700;
  padding: 3px 9px;
  border-radius: 20px;
}

.frames-row {
  display: flex;
  gap: 10px;
  padding: 14px 16px;
}

.photo-frame {
  flex: 1;
  background: var(--frame-bg);
  border: 2px solid var(--frame-border);
  border-radius: 6px;
  margin: 0;
  padding: 8px 6px 6px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
}

.frame-1 { border-top: 4px solid var(--frame-1-accent); }
.frame-2 { border-top: 4px solid var(--frame-2-accent); }
.frame-3 { border-top: 4px solid var(--frame-3-accent); }
.frame-4 { border-top: 4px solid var(--frame-4-accent); }

.photo-inner {
  font-size: 32px;
  line-height: 1;
  background: var(--strip-bg);
  border-radius: 4px;
  width: 52px;
  height: 52px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.photo-frame figcaption {
  font-size: 10px;
  font-weight: 600;
  color: var(--caption-text);
  text-align: center;
}

.strip-footer {
  background: var(--footer-bg);
  border-top: 1px solid var(--strip-border);
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 9px 16px;
}

.footer-label {
  font-size: 11px;
  color: var(--footer-text);
}

.print-btn {
  background: var(--btn-bg);
  color: var(--btn-text);
  border: none;
  border-radius: 6px;
  font-size: 12px;
  font-weight: 600;
  padding: 5px 12px;
  cursor: pointer;
}
